before:
```swift
func visits(_ limit: Int) -> (before: Int, after: Int) {
    var before = 0
    while before < limit {
        before += 1
    }
    var after = 0
    repeat {
        after += 1
    } while after < limit
    return (before, after)
}
let result = visits(3)
print(result.before)
print(result.after)
```
Output:
```text
3
3
```

